documents.donors:
yamaa: "1.0"
type: spec
domain: ADLES
keys: [STUDYID, USUBJID]
input:
  SUBJ: {path: subj.csv, types: {AGE: int, OUTCOME: int}}
base: SUBJ
output: {path: out.csv, columns: [STUDYID, USUBJID, AGE, OUTCOME, SDAGE, DONORID]}
intermediates:
  - id: DONOR
    dataset: SUBJ
    key: [STUDYID]
    filter: "SUBJ.OUTCOME IS NOT NULL AND ADLES.OUTCOME IS NULL"
    order_by: [SUBJ.DIST, SUBJ.USUBJID]
    keep: first
    derivations:
      DIST: "ABS(AGE - ADLES.AGE) / ADLES.SDAGE"
columns:
  - {name: STUDYID, type: str, derivation: SUBJ.STUDYID}
  - {name: USUBJID, type: str, derivation: SUBJ.USUBJID}
  - {name: AGE, type: int, derivation: SUBJ.AGE}
  - {name: OUTCOME, type: int, derivation: SUBJ.OUTCOME}
  - {name: SDAGE, type: float, derivation: {aggregate: {expr: "STDDEV(AGE)", group_by: [STUDYID]}}}
  - {name: DONORID, type: str, derivation: DONOR.USUBJID}
